-- quiz.sql
-- Connect to the quiz database
\c quiz;

-- Drop existing tables to ensure a clean slate (optional, remove if you want to keep existing data)
DROP TABLE IF EXISTS users, nature, art, history, geography, science, politics, music, film, celebrities;

-- Create users table
CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    password VARCHAR(50) NOT NULL,
    nature_coins INT DEFAULT 0,
    art_coins INT DEFAULT 0,
    history_coins INT DEFAULT 0,
    geography_coins INT DEFAULT 0,
    science_coins INT DEFAULT 0,
    politics_coins INT DEFAULT 0,
    music_coins INT DEFAULT 0,
    film_coins INT DEFAULT 0,
    celebrities_coins INT DEFAULT 0
);

-- Create tables for quiz topics (corrected spelling: geographie -> geography, celebereties -> celebrities)
CREATE TABLE nature (
    id SERIAL PRIMARY KEY,
    module VARCHAR(100),
    submodule VARCHAR(100),
    difficulty_level INT CHECK (difficulty_level BETWEEN 1 AND 3),
    question TEXT NOT NULL,
    correct_answer TEXT NOT NULL,
    wrong_answer1 TEXT NOT NULL,
    wrong_answer2 TEXT NOT NULL,
    wrong_answer3 TEXT,
    wrong_answer4 TEXT,
    wrong_answer5 TEXT
);

